patches.old:
{aiNotice && (
  <p role="status" className="text-xs text-ok">
    {aiNotice}
  </p>
)}
{aiError && (
  <div role="alert" className="rounded-xl bg-bad-soft p-3 text-xs text-bad">
    {aiError.includes('videoRequiresVerifiedFlow')
      ? 'La modification de vidéo par l’IA est temporairement indisponible (flux en cours de validation).'
      : aiError}
  </div>
)}

patches.new:
{aiNotice && (
  <p role="status" className="min-w-0 break-words text-xs text-ok">
    {aiNotice}
  </p>
)}
{aiError && (
  <div role="alert" className="min-w-0 max-w-full break-words rounded-xl bg-bad-soft p-3 text-xs text-bad">
    {aiError.includes('videoRequiresVerifiedFlow')
      ? 'La modification de vidéo par l’IA est temporairement indisponible (flux en cours de validation).'
      : aiError}
  </div>
)}
